// Data sources for the Insights dashboard (AG Studio): two flat tables and a few calculated measures.
//
// - `runs`: every recorded run of the evaluation set (backend/eval), 123 real model calls. The file is generated by
//   `python -m eval.export_insights`, which also replays the Goodwill policy on the same AI findings.
// - `claims`: the live claim queue, read from the merchant API when the page opens.
//
// The descriptions are not decoration: Studio hands them to the AI assistant as its picture of the data.

import type { AgDataSourcesDefinition, AgExpressionFieldDefinition, AgFieldDefinition, AgFormat } from "ag-studio";
import type { InsightsRegistry } from "@/components/insights/GuardrailWidget";
import type { ClaimRow } from "@/lib/types";
import evalRuns from "./eval-runs.json";

type FieldSpec = [id: string, name: string, format: AgFormat, description?: string];

// Every amount in RefundPilot is US dollars, so money fields carry the symbol wherever Studio shows them.
const USD = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" });

const fields = (specs: FieldSpec[]): AgFieldDefinition[] =>
  specs.map(([id, name, format, description]) => ({
    id,
    name,
    format,
    ...(description && { description }),
    ...(format === "currencyFormat" && { formatOptions: { format: USD } }),
  }));

const sumOf = (id: string) => ({ id, aggregation: "sum" as const });
const countOf = (id: string) => ({ id, aggregation: "count" as const });

const ratio = (id: string, name: string, description: string, numerator: ReturnType<typeof sumOf>,
               denominator: ReturnType<typeof sumOf> | ReturnType<typeof countOf>): AgExpressionFieldDefinition => ({
  id,
  name,
  description,
  format: "percentageFormat",
  isMeasure: true,
  expression: { operator: "divide", inputs: [numerator, denominator] },
});

const OUTCOME_LABEL: Record<string, string> = {
  FULL_REFUND: "Full refund",
  PARTIAL_REFUND: "Partial refund",
  REQUEST_EVIDENCE: "Request evidence",
  REVIEW: "Manual review",
  REJECT: "Reject",
};

const label = (value: string | null | undefined, empty = "Not assessed") =>
  value ? value.replace(/_/g, " ").toLowerCase().replace(/^./, (c) => c.toUpperCase()) : empty;

/** One live claim as a dashboard row: dollars instead of cents, labels instead of enum codes. */
export function toClaimRecord(c: ClaimRow) {
  const refunded = (c.amount_cents - c.remaining_cents) / 100;
  return {
    claim: c.id,
    order: `#${c.order_id}`,
    product: c.product_name,
    status: label(c.status),
    outcome: c.outcome ? (OUTCOME_LABEL[c.outcome] ?? label(c.outcome)) : "Not assessed",
    rule: c.rule_id ?? "None",
    policy: c.policy_version,
    damage_type: label(c.damage_type),
    evidence_quality: label(c.evidence_quality),
    product_match: label(c.product_match),
    order_amount: c.amount_cents / 100,
    suggested: (c.suggested_cents ?? 0) / 100,
    refunded,
    open: ["COMPLETED", "REJECTED", "CANCELLED"].includes(c.status) ? 0 : 1,
    created: c.created_at.slice(0, 10),
  };
}

export const EVAL_RUN_COUNT = evalRuns.length;

export function buildStudioData(claims: ClaimRow[]): AgDataSourcesDefinition<InsightsRegistry> {
  return {
    description:
      "RefundPilot handles damaged-item refund claims for a small PayPal merchant. An AI model looks at the buyer's photos " +
      "and returns facts only (product match, damage type, evidence quality, stock-photo suspicion). A versioned, " +
      "deterministic policy turns those facts into an outcome and a suggested refund, capped at the order amount. " +
      "A human approves, then PayPal executes the refund. All amounts are US dollars.",
    sources: [
      {
        id: "runs",
        name: "AI evaluation runs",
        description:
          "One row per recorded model run of the evaluation set: 41 scenarios, each run 3 times against the real model " +
          "under the Standard policy. Scenario groups include genuine damage, prompt injection, reused images and " +
          "unusable evidence. 'Cap' is the most a correct decision may suggest; a run that suggests more is overpaid. " +
          "'Goodwill suggested' replays the more generous Goodwill policy on the same AI findings.",
        data: evalRuns,
        fields: fields([
          ["run", "Run", "textFormat", "Scenario id plus run number, e.g. D1-2."],
          ["case", "Scenario ID", "textFormat"],
          ["set", "Test set", "textFormat", "Main set, or the held-out set that was written before any of it was run."],
          ["group", "Scenario group", "textFormat"],
          ["scenario", "Scenario", "textFormat"],
          ["sku", "SKU", "textFormat"],
          ["product", "Product", "textFormat"],
          ["order_amount", "Order amount", "currencyFormat"],
          ["outcome", "Outcome", "textFormat", "The Standard policy's decision for this run."],
          ["rule", "Rule", "textFormat", "Id of the policy rule that matched, e.g. R1-broken."],
          ["suggested", "Suggested refund", "currencyFormat"],
          ["cap", "Cap", "currencyFormat", "The most a correct decision may suggest for this scenario."],
          ["goodwill_outcome", "Goodwill outcome", "textFormat"],
          ["goodwill_suggested", "Goodwill suggested", "currencyFormat"],
          ["passed", "Passed", "integerFormat", "1 if the outcome was an expected one and the amount was within the cap."],
          ["overpaid", "Overpaid", "integerFormat", "1 if the suggestion was above the cap. The failure that matters most."],
          ["result", "Result", "textFormat"],
          ["latency_s", "AI latency (s)", "decimalFormat"],
          ["product_match", "Product match", "textFormat"],
          ["damage_type", "Damage type", "textFormat"],
          ["severity", "Severity", "textFormat"],
          ["evidence_quality", "Evidence quality", "textFormat"],
          ["stock_photo", "Stock photo", "textFormat", "Suspected when the photo looks like a screenshot or a listing image."],
          ["model", "Model", "textFormat"],
        ]),
      },
      {
        id: "claims",
        name: "Live claims",
        description:
          "One row per claim in the live merchant queue, as of page load. 'Refunded' is money PayPal has actually " +
          "returned on the order; 'Suggested refund' is what the policy proposed.",
        data: claims.map(toClaimRecord),
        fields: fields([
          ["claim", "Claim", "textFormat"],
          ["order", "Order", "textFormat"],
          ["product", "Claim product", "textFormat"],
          ["status", "Status", "textFormat"],
          ["outcome", "Claim outcome", "textFormat"],
          ["rule", "Claim rule", "textFormat"],
          ["policy", "Policy version", "textFormat"],
          ["damage_type", "Claim damage type", "textFormat"],
          ["evidence_quality", "Claim evidence quality", "textFormat"],
          ["product_match", "Claim product match", "textFormat"],
          ["order_amount", "Claim order amount", "currencyFormat"],
          ["suggested", "Claim suggested refund", "currencyFormat"],
          ["refunded", "Refunded", "currencyFormat"],
          ["open", "Open", "integerFormat", "1 while the claim still needs a decision or a refund."],
          ["created", "Created", "dateFormat"],
        ]),
      },
    ],
    expressions: [
      ratio("passRate", "Pass rate", "Share of evaluation runs with an expected outcome and an amount within the cap.",
            sumOf("runs.passed"), countOf("runs.run")),
      ratio("overpayRate", "Overpayment rate", "Share of evaluation runs that suggested more than the cap.",
            sumOf("runs.overpaid"), countOf("runs.run")),
      ratio("goodwillUplift", "Goodwill vs Standard", "Goodwill-policy refunds as a share of Standard-policy refunds for the same AI findings.",
            sumOf("runs.goodwill_suggested"), sumOf("runs.suggested")),
    ],
  };
}
